const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry around North Crimean Canal in Ukraine
  const canalRegion = ee.Geometry.Polygon([
    [[34.0, 46.4], [34.5, 46.4], [34.5, 46.2], [34.0, 46.2], [34.0, 46.4]]
  ]);

  // 2. Data Acquisition - Sentinel-2 for vegetation analysis
  const startDate = '2023-06-03';
  const endDate = '2023-07-19';

  let s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(canalRegion)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  // Check collection size
  const colSize = s2Col.size().getInfo();
  console.log(`Sentinel-2 Images: ${colSize}`);

  if (colSize === 0) {
    console.log("No Sentinel-2 data found, trying Landsat 8...");
    s2Col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(startDate, endDate)
      .filterBounds(canalRegion);

    const landsatSize = s2Col.size().getInfo();
    console.log(`Landsat 8 Images: ${landsatSize}`);

    if (landsatSize === 0) {
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Cloud masking and NDVI calculation
  function maskClouds(image) {
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const qa = image.select('QA60');
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  const processedCol = s2Col.map(maskClouds).map(addNDVI);
  const medianImage = processedCol.median();

  // 4. Check valid pixels
  const pixelCount = medianImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: canalRegion,
    scale: 100,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Calculate mean NDVI
  const ndviStats = medianImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: canalRegion,
    scale: 100,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Mean NDVI: ${ndviStats ? ndviStats.toFixed(3) : 'NaN'}`);

  // 6. Validation and final answer
  if (ndviStats === null || ndviStats === undefined || isNaN(ndviStats)) {
    console.log("<answer>C3</answer>");
  } else if (ndviStats < 0.3) { // Threshold for "brown" vegetation
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
